28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    /**
66	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
67	     * household with an existing owner. When {@code true}, creation is allowed even if
68	     * another owner already has the same lastName and address.
69	     */
70	    @Transient
71	    private boolean sharesHousehold;
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    public String getAddress() {
77	        return this.address;
78	    }
79	
80	    public void setAddress(String address) {
81	        this.address = address;
82	    }
83	
84	    public String getCity() {
85	        return this.city;
86	    }
87	
88	    public void setCity(String city) {
89	        this.city = city;
90	    }
91	
92	    public String getTelephone() {
93	        return this.telephone;
94	    }
95	
96	    public void setTelephone(String telephone) {
97	        this.telephone = telephone;
98	    }
99	
100	    public String getEmail() {
101	        return this.email;
102	    }
103	
104	    public void setEmail(String email) {
105	        this.email = email;
106	    }
107	
108	    public LocalDate getRegistrationDate() {
109	        return this.registrationDate;
110	    }
111	
112	    public void setRegistrationDate(LocalDate registrationDate) {
113	        this.registrationDate = registrationDate;
114	    }
115	
116	    public String getCustomerCode() {
117	        return this.customerCode;
118	    }
119	
120	    public void setCustomerCode(String customerCode) {
121	        this.customerCode = customerCode;
122	    }
123	
124	    public String getHouseholdId() {
125	        return this.householdId;
126	    }
127	
128	    public void setHouseholdId(String householdId) {
129	        this.householdId = householdId;
130	    }
131	
132	    public boolean isSharesHousehold() {
133	        return this.sharesHousehold;
134	    }
135	
136	    public void setSharesHousehold(boolean sharesHousehold) {
137	        this.sharesHousehold = sharesHousehold;
138	    }
139	
140	    protected Set<Pet> getPetsInternal() {
141	        if (this.pets == null) {
142	            this.pets = new HashSet<>();
143	        }
144	        return this.pets;
145	    }
146	
147	    protected void setPetsInternal(Set<Pet> pets) {
148	        this.pets = pets;
149	    }
150	
151	    public List<Pet> getPets() {
152	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
153	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
154	        return Collections.unmodifiableList(sortedPets);
155	    }
156	
157	    public void setPets(List<Pet> pets) {
158	        this.pets = new HashSet<>(pets);
159	    }
160	
161	    public void addPet(Pet pet) {
162	        getPetsInternal().add(pet);
163	        pet.setOwner(this);
164	    }
165	
166	    /**
167	     * Return the Pet with the given name, or null if none found for this Owner.
168	     *
169	     * @param name to test
170	     * @return true if pet name is already in use
171	     */
172	    public Pet getPet(String name) {
173	        return getPet(name, false);
174	    }
175	
176	    /**
177	     * Return the Pet with the given name, or null if none found for this Owner.
178	     *
179	     * @param name to test
180	     * @return true if pet name is already in use
181	     */
182	    public Pet getPet(String name, boolean ignoreNew) {
183	        name = name.toLowerCase();
184	        for (Pet pet : getPetsInternal()) {
185	            if (!ignoreNew || !pet.isNew()) {
186	                String compName = pet.getName();
187	                compName = compName.toLowerCase();
188	                if (compName.equals(name)) {
189	                    return pet;
190	                }
191	            }
192	        }
193	        return null;
194	    }
195	
196	    public Pet getPet(Integer petId) {
197	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
198	    }
199	
200	    @Override
201	    public String toString() {
202	        return new ToStringCreator(this)
203	
204	            .append("id", this.getId())
205	            .append("new", this.isNew())
206	            .append("lastName", this.getLastName())
207	            .append("firstName", this.getFirstName())
208	            .append("address", this.address)
209	            .append("city", this.city)
210	            .append("telephone", this.telephone)
211	            .toString();
212	    }
213	}
