40	/**
41	 * Mostly used as a facade for all Petclinic controllers
42	 * Also a placeholder for @Transactional and @Cacheable annotations
43	 *
44	 * @author Michael Isvy
45	 * @author Vitaliy Fedoriv
46	 */
47	@Service
48	public class ClinicServiceImpl implements ClinicService {
49	
50	    private final PetRepository petRepository;
51	    private final VetRepository vetRepository;
52	    private final OwnerRepository ownerRepository;
53	    private final VisitRepository visitRepository;
54	    private final SpecialtyRepository specialtyRepository;
55	    private final PetTypeRepository petTypeRepository;
56	
57	    public ClinicServiceImpl(
58	        PetRepository petRepository,
59	        VetRepository vetRepository,
60	        OwnerRepository ownerRepository,
61	        VisitRepository visitRepository,
62	        SpecialtyRepository specialtyRepository,
63	        PetTypeRepository petTypeRepository) {
64	        this.petRepository = petRepository;
65	        this.vetRepository = vetRepository;
66	        this.ownerRepository = ownerRepository;
67	        this.visitRepository = visitRepository;
68	        this.specialtyRepository = specialtyRepository;
69	        this.petTypeRepository = petTypeRepository;
70	    }
71	
72	    @Override
73	    @Transactional(readOnly = true)
74	    public Collection<Pet> findAllPets() throws DataAccessException {
75	        return petRepository.findAll();
76	    }
77	
78	    @Override
79	    @Transactional(readOnly = true)
80	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
81	        return petRepository.findAll(pageable);
82	    }
83	
84	    @Override
85	    @Transactional
86	    public void deletePet(Pet pet) throws DataAccessException {
