89	
90	    @Override
91	    @Transactional(readOnly = true)
92	    public Visit findVisitById(int visitId) throws DataAccessException {
93	        return findEntityById(() -> visitRepository.findById(visitId));
94	    }
95	
96	    @Override
97	    @Transactional(readOnly = true)
98	    public Collection<Visit> findAllVisits() throws DataAccessException {
99	        return visitRepository.findAll();
100	    }
101	
102	    @Override
103	    @Transactional
104	    public void deleteVisit(Visit visit) throws DataAccessException {
