130	    }
131	
132	    @Override
133	    @Transactional(readOnly = true)
134	    public Collection<Owner> findAllOwners() throws DataAccessException {
135	        return ownerRepository.findAll();
136	    }
137	
138	    @Override
139	    @Transactional(readOnly = true)
140	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
141	        if (lastName != null) {
142	            return ownerRepository.findByLastName(lastName, pageable);
143	        }
144	        return ownerRepository.findAll(pageable);
145	    }
146	
147	    @Override
148	    @Transactional
149	    public void deleteOwner(Owner owner) throws DataAccessException {
150	        ownerRepository.delete(owner);
151	    }
152	
153	    @Override
154	    @Transactional(readOnly = true)
155	    public PetType findPetTypeById(int petTypeId) {
156	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
157	    }
158	
159	    @Override
160	    @Transactional(readOnly = true)
161	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
162	        return petTypeRepository.findAll();
163	    }
164	
165	    @Override
166	    @Transactional
167	    public void savePetType(PetType petType) throws DataAccessException {
168	        petTypeRepository.save(petType);
169	    }
170	
171	    @Override
172	    @Transactional
173	    public void deletePetType(PetType petType) throws DataAccessException {
174	        petTypeRepository.delete(petType);
175	    }
176	
177	    @Override
178	    @Transactional(readOnly = true)
179	    public Specialty findSpecialtyById(int specialtyId) {
180	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
181	    }
182	
183	    @Override
184	    @Transactional(readOnly = true)
185	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
186	        return specialtyRepository.findAll();
187	    }
188	
189	    @Override
190	    @Transactional
191	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
192	        specialtyRepository.save(specialty);
193	    }
194	
195	    @Override
196	    @Transactional
197	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
198	        specialtyRepository.delete(specialty);
199	    }
200	
201	    @Override
202	    @Transactional(readOnly = true)
203	    public Collection<PetType> findPetTypes() throws DataAccessException {
204	        return petRepository.findPetTypes();
205	    }
206	
207	    @Override
208	    @Transactional(readOnly = true)
209	    public Owner findOwnerById(int id) throws DataAccessException {
210	        return findEntityById(() -> ownerRepository.findById(id));
211	    }
212	
213	    @Override
214	    @Transactional(readOnly = true)
215	    public Pet findPetById(int id) throws DataAccessException {
216	        return findEntityById(() -> petRepository.findById(id));
217	    }
218	
219	    @Override
220	    @Transactional
221	    public void savePet(Pet pet) throws DataAccessException {
222	        pet.setType(findPetTypeById(pet.getType().getId()));
223	        petRepository.save(pet);
224	    }
225	
226	    @Override
227	    @Transactional
228	    public void saveVisit(Visit visit) throws DataAccessException {
229	        visitRepository.save(visit);
230	
231	    }
232	
233	    @Override
234	    @Transactional(readOnly = true)
235	    public Collection<Vet> findVets() throws DataAccessException {
236	        return vetRepository.findAll();
237	    }
238	
239	    @Override
240	    @Transactional
241	    public void saveOwner(Owner owner) throws DataAccessException {
242	        if (owner.getTelephone() != null) {
243	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
244	        }
245	        if (owner.getEmail() != null) {
246	            owner.setEmail(normalizeEmail(owner.getEmail()));
247	        }
248	        if (owner.getRegistrationDate() == null) {
249	            owner.setRegistrationDate(LocalDate.now());
250	        }
251	        if (owner.getCustomerCode() == null) {
252	            owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
253	        }
254	        assertTelephoneUnique(owner, owner.getTelephone());
255	        List<Owner> household = findHouseholdMembers(owner);
256	        assertHouseholdAllowed(owner, household);
257	        assignHousehold(owner, household);
258	        ownerRepository.save(owner);
259	    }
260	
261	    /**
262	     * Build a {@code customerCode} formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
263	     * upper-cased first three letters of {@code lastName} and NNNN is a global 4-digit
264	     * zero-padded sequence equal to one more than the current number of owners.
265	     */
266	    private String generateCustomerCode(String lastName) {
267	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
268	        long sequence = ownerRepository.findAll().size() + 1L;
269	        return String.format("%s-%04d", prefix, sequence);
270	    }
271	
272	    private static String normalizeEmail(String email) {
273	        return email == null ? null : email.toLowerCase(Locale.ROOT);
274	    }
275	
276	    private static String normalizeTelephone(String telephone) {
277	        return telephone == null ? null : E164Telephone.toE164(telephone);
278	    }
279	
280	    /**
281	     * Rejects saving {@code owner} when its {@code normalized} telephone is already used by any
282	     * other owner, so no two owners can share a telephone number.
283	     *
284	     * @throws DuplicateTelephoneException if another owner already has the same normalized telephone
285	     */
286	    private void assertTelephoneUnique(Owner owner, String normalized) {
287	        if (normalized == null || normalized.isEmpty()) {
288	            return;
289	        }
290	        for (Owner existing : ownerRepository.findAll()) {
291	            if (!existing.getId().equals(owner.getId())
292	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
293	                throw new DuplicateTelephoneException(normalized);
294	            }
295	        }
296	    }
297	
298	    /**
299	     * Returns the existing owners that share both {@code lastName} and {@code address} (compared
300	     * case-insensitively with collapsed whitespace) with a new {@code owner} — i.e. the members of
301	     * the household it would join. Returns an empty list for an update to an existing owner or when
302	     * either household value is blank, so household rules only apply to genuine new members.
303	     */
304	    private List<Owner> findHouseholdMembers(Owner owner) {
305	        if (!owner.isNew()) {
306	            return List.of();
307	        }
308	        String lastName = normalizeHouseholdValue(owner.getLastName());
309	        String address = normalizeHouseholdValue(owner.getAddress());
310	        if (lastName.isEmpty() || address.isEmpty()) {
311	            return List.of();
312	        }
313	        List<Owner> household = new ArrayList<>();
314	        for (Owner existing : ownerRepository.findAll()) {
315	            if (!existing.getId().equals(owner.getId())
316	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
317	                    && address.equals(normalizeHouseholdValue(existing.getAddress()))) {
318	                household.add(existing);
319	            }
320	        }
321	        return household;
322	    }
323	
324	    /**
325	     * Pure guard: rejects creating {@code owner} when it would join a non-empty {@code household}
326	     * without acknowledging the shared household via {@link Owner#isSharesHousehold()}. Returns
327	     * without side effects otherwise.
328	     *
329	     * @throws DuplicateHouseholdException if another owner already lives at the same household and
330	     *                                     the request does not acknowledge the shared household
331	     */
332	    private void assertHouseholdAllowed(Owner owner, List<Owner> household) {
333	        if (!household.isEmpty() && !owner.isSharesHousehold()) {
334	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
335	        }
336	    }
337	
338	    /**
339	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
340	     * owner and every matching existing member that lacks one are given the same stable
341	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
342	     * is empty.
343	     */
344	    private void assignHousehold(Owner owner, List<Owner> household) {
